const ELITE_TRAITS={swift:{name:'疾走',description:'移動速度40%増'},armored:{name:'重装',description:'受けるダメージ30%減'},renewal:{name:'再生',description:'3秒間被弾しないと毎秒最大ライフ1%回復'}};
function promoteEnemy(e,traits){if(!e||e.boss||e.elite||e.hp<=0)return false;let selected=[...new Set(traits)].filter(t=>Object.hasOwn(ELITE_TRAITS,t));if(!selected.length)return false;e.elite=selected;e.max*=2.2;e.hp*=2.2;e.sinceHit=0;return true}
const normalRoomSpawn=spawnRoom;spawnRoom=room=>{let first=enemies.length;normalRoomSpawn(room);if(![2,4,6,7].includes(room.id))return;let random=seeded(dungeon.seed+room.id*104729),pool=Object.keys(ELITE_TRAITS),traits=[pool.splice(Math.floor(random()*pool.length),1)[0]];if(floor>=5)traits.push(pool[Math.floor(random()*pool.length)]);promoteEnemy(enemies[first],traits);feed('希少な亡者：'+traits.map(t=>ELITE_TRAITS[t].name+'（'+ELITE_TRAITS[t].description+'）').join(' / '))};
const eliteBaseAnimation=animateEnemy;animateEnemy=(e,dt)=>{if(e.hp<=0)return;if(e.elite){e.sinceHit=(e.sinceHit||0)+dt;if(e.elite.includes('renewal')&&e.sinceHit>3&&dist(e,p)<650)e.hp=Math.min(e.max,e.hp+e.max*.01*Math.min(dt,e.sinceHit-3))}eliteBaseAnimation(e,dt)};
const eliteBaseHit=hit;hit=(e,d)=>{if(e.hp<=0)return;let alive=e.hp>0;if(e.elite)e.sinceHit=0;eliteBaseHit(e,d*(e.elite?.includes('armored')?.7:1));if(alive&&e.hp<=0&&e.elite&&!e.eliteRewarded){e.eliteRewarded=true;let gold=25+floor*5;p.gold+=gold;drops.push({x:e.x+18,y:e.y,item:rollItem(randomGearSlot(),true)});feed('希少な亡者を討伐 · '+gold+'G / レア装備');say('希少な装備が落ちた');save()}};
function drawEliteLabel(e,s,size){if(!e.elite)return;groundRing(e.x,e.y,31,'#e0b56c',2);if(typeof enemyNameVisible==='function'&&!enemyNameVisible(e))return;ctx.textAlign='center';if(e.species){ctx.fillStyle='#f0d591';ctx.font='10px sans-serif';ctx.fillText('希少 · '+e.elite.map(t=>ELITE_TRAITS[t].name).join(' · '),s.x,s.y-size*.8-24);return;}ctx.fillStyle='#f0d591';ctx.font='bold 12px sans-serif';ctx.fillText('希少な亡者',s.x,s.y-size*.8-24);ctx.font='10px sans-serif';ctx.fillText(e.elite.map(t=>ELITE_TRAITS[t].name).join(' · '),s.x,s.y-size*.8-10)}
